(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035+t*0.15)*8 + Math.cos((y+w1y)*0.025-t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03-t*0.18)*8 + Math.sin((x+w1x)*0.028+t*0.22)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*55, 0.085, 1.8]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*0.5;
  }
  const act=aS/8, inh=iS/8, harm=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.06+sy*0.05-t*0.6)+Math.sin(sx*0.02-sy*0.06+t*1.4))/4+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin((sx*0.7-sy*1.3)*0.08+t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.08+ang*2-t*2.0)+Math.sin(dist*0.06-ang*5+t*0.8))*0.2;
  const detail=Math.sin(Math.sin(sx*0.08+t)*4+Math.cos(sy*0.09-t*0.7)*3)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2+harm*0.4+detail)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-t*0.5)*Math.cos(sy*0.18+t*0.3)*0.3)*1.5)*0.3;
  const blend=reaction*0.7+cell*0.2+detail*0.1, v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,75],[15,70,105],[20,120,130],[45,165,135],[130,190,100],[210,200,70],[230,160,55],[215,105,55],[180,60,60],[130,35,70],[75,20,65],[35,15,55],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,1-Math.abs(reaction))*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
